# AUTOGENERATED KERNEL (LLM)
# Source: LLM-generated candidate implementation
# Status: Experimental / uncurated
# Expectation: Correctness-first, performance not representative

import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_M": 32, "BLOCK_N": 32, "BLOCK_K": 32, "GROUP_SIZE_M": gs},
        )
        for gs in [1, 2, 4, 8]
    ],
    key=["M", "N", "K"],
)
@triton.jit
def _batched_matmul_kernel(
    A_ptr,
    B_ptr,
    C_ptr,
    M,
    N,
    K,
    stride_ab: tl.constexpr,
    stride_am: tl.constexpr,
    stride_ak: tl.constexpr,
    stride_bb: tl.constexpr,
    stride_bk: tl.constexpr,
    stride_bn: tl.constexpr,
    stride_cb: tl.constexpr,
    stride_cm: tl.constexpr,
    stride_cn: tl.constexpr,
    BATCH: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    GROUP_SIZE_M: tl.constexpr,
):
    pid = tl.program_id(0)

    num_pid_m = tl.cdiv(M, BLOCK_M)
    num_pid_n = tl.cdiv(N, BLOCK_N)
    num_tiles_mn = num_pid_m * num_pid_n

    batch_id = pid // num_tiles_mn
    tile_id = pid % num_tiles_mn

    num_pid_in_group = GROUP_SIZE_M * num_pid_n
    group_id = tile_id // num_pid_in_group
    first_pid_m = group_id * GROUP_SIZE_M
    group_size_m = tl.minimum(num_pid_m - first_pid_m, GROUP_SIZE_M)
    pid_m = first_pid_m + ((tile_id % num_pid_in_group) % group_size_m)
    pid_n = (tile_id % num_pid_in_group) // group_size_m

    batch_offset_a = batch_id.to(tl.int64) * stride_ab
    batch_offset_b = batch_id.to(tl.int64) * stride_bb
    batch_offset_c = batch_id.to(tl.int64) * stride_cb

    a_desc = tl.make_tensor_descriptor(
        base=A_ptr + batch_offset_a,
        shape=(M, K),
        strides=(stride_am, stride_ak),
        block_shape=(BLOCK_M, BLOCK_K),
    )

    b_desc = tl.make_tensor_descriptor(
        base=B_ptr + batch_offset_b,
        shape=(K, N),
        strides=(stride_bk, stride_bn),
        block_shape=(BLOCK_K, BLOCK_N),
    )

    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)
    for off_k in range(0, K, BLOCK_K):
        a = a_desc.load([pid_m * BLOCK_M, off_k])
        b = b_desc.load([off_k, pid_n * BLOCK_N])
        acc += tl.dot(a, b)
    c_desc = tl.make_tensor_descriptor(
        base=C_ptr + batch_offset_c,
        shape=(M, N),
        strides=(stride_cm, stride_cn),
        block_shape=(BLOCK_M, BLOCK_N),
    )
    c_desc.store([pid_m * BLOCK_M, pid_n * BLOCK_N], acc.to(C_ptr.type.element_ty))


class Model(nn.Module):
    def __init__(self):
        super(Model, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        BATCH, M, K = A.shape
        _, _, N = B.shape

        A = A.contiguous()
        B = B.contiguous()
        C = torch.empty((BATCH, M, N), device=A.device, dtype=A.dtype)

        def grid(META):
            assert (
                M % META["BLOCK_M"] == 0
                and N % META["BLOCK_N"] == 0
                and K % META["BLOCK_K"] == 0
            ), (
                "M, N and K must be divisible by BLOCK_M, BLOCK_N and BLOCK_K respectively"
            )
            return (
                BATCH
                * triton.cdiv(M, META["BLOCK_M"])
                * triton.cdiv(N, META["BLOCK_N"]),
            )

        _batched_matmul_kernel[grid](
            A,
            B,
            C,
            M,
            N,
            K,
            A.stride(0),
            A.stride(1),
            A.stride(2),
            B.stride(0),
            B.stride(1),
            B.stride(2),
            C.stride(0),
            C.stride(1),
            C.stride(2),
            BATCH=BATCH,
            assume_in_bounds=True,
        )
        return C


batch_size = 128
m = 128 * 4
k = 256 * 4
n = 512 * 4


def get_inputs():
    A = torch.rand(batch_size, m, k, dtype=torch.bfloat16)
    B = torch.rand(batch_size, k, n, dtype=torch.bfloat16)
    return [A, B]


